const knownTypes = new Set(["added", "removed", "price_changed", "availability_changed", "fields_changed"]);
const clean = (value, limit = 120) => {
  if (value === null || value === undefined || value === "") return "—";
  const text = String(value).replace(/[\u0000-\u001f\u007f]+/g, " ").replace(/\s+/g, " ").trim().slice(0, limit);
  return text || "—";
};
const rows = $input.all().map(item => item.json).filter(row => row.changeType && row.changeType !== "unchanged");
if (rows.length === 0) return [];
const primaryCounts = {};
const allLabelCounts = {};
for (const row of rows) {
  const primary = knownTypes.has(row.changeType) ? row.changeType : "other";
  primaryCounts[primary] = (primaryCounts[primary] || 0) + 1;
  const labels = Array.isArray(row.changeTypes) && row.changeTypes.length ? row.changeTypes : [row.changeType];
  for (const rawLabel of labels) {
    const label = knownTypes.has(rawLabel) ? rawLabel : "other";
    allLabelCounts[label] = (allLabelCounts[label] || 0) + 1;
  }
}
const renderCounts = counts => Object.entries(counts).sort(([a], [b]) => a.localeCompare(b)).map(([type, count]) => `  ${type}: ${count}`);
const maxRows = 50;
const itemLines = rows.slice(0, maxRows).map(row => {
  const parts = [`${clean(row.key)}${row.title ? " — " + clean(row.title) : ""}`];
  const labels = Array.isArray(row.changeTypes) && row.changeTypes.length ? row.changeTypes : [row.changeType];
  parts.push(`changes: ${labels.map(label => knownTypes.has(label) ? label : "other").join(", ")}`);
  if (row.oldPrice !== null && row.oldPrice !== undefined || row.newPrice !== null && row.newPrice !== undefined) {
    const currency = clean(row.currency, 12);
    parts.push(`price: ${clean(row.oldPrice)} ${currency} → ${clean(row.newPrice)} ${currency}`);
  }
  if (row.oldAvailability !== null && row.oldAvailability !== undefined || row.newAvailability !== null && row.newAvailability !== undefined) {
    parts.push(`availability: ${clean(row.oldAvailability)} → ${clean(row.newAvailability)}`);
  }
  return `- ${parts.join(" | ")}`;
});
if (rows.length > maxRows) itemLines.push(`- ${rows.length - maxRows} additional changed items omitted; open the full run dataset.`);
const config = $("Configure supplier feed").first().json;
const runHistory = "https://console.apify.com/actors/hPQawsVIn5gAIhk8c/runs";
const lines = [
  `${rows.length} changed items detected for ${clean(config.baselineName)}.`,
  "Primary change type per item:",
  ...renderCounts(primaryCounts),
  "All change labels across items:",
  ...renderCounts(allLabelCounts),
  "Changed items (up to 50):",
  ...itemLines,
  `Full dataset and run history: ${runHistory}`,
];
return [{json: {
  alertEmail: config.alertEmail,
  baselineName: config.baselineName,
  changeCount: rows.length,
  summaryText: lines.join("\n"),
}}];
